from pathlib import Path
from PIL import Image
import json,hashlib
from datetime import datetime,timezone
T=Path(__file__).resolve().parent;Q=T/'qa/local-repair-20261013'
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
j=read(Q/'composition-v6.json');f=Path(j['candidate']);assert sha(f)==j['candidateSha256']
with Image.open(f) as im:assert im.size==(4096,4096) and im.mode=='RGB'
review={'tile':T.name,'reviewedAtUtc':datetime.now(timezone.utc).isoformat(),'candidate':str(f),'candidateSha256':sha(f),'status':'best_complete_candidate_local_boundary_repairs_deferred','internalPassed4kCount':0,'formalAcceptedCount':0,'baselineReview':str(Q/'baseline-review-v1.json'),'baselineSeamCountReviewed':24,'baselineIntersectionCountReviewed':9,'unchangedAreasReviewReused':True,'composition':str(Q/'composition-v6.json'),'priorComposition':str(Q/'composition-v3.json'),'newReviewedWindows':[str(Q/x) for x in ['roof-left-composed-v3.png','wall-right-composed-v5.png','leaf-right-composed-v4.png','rock-bottom-composed-v6.png','rock-top-v6.png','rock-left-v6.png','rock-bottom-v6.png','wall-top-v6.png','wall-bottom-v6.png','wall-right-v6.png']],'resolvedFindings':['roof y3072 horizontal rectangular step removed while retaining ceramic geometry and gold hip ridge','central wall/leaf cutoff and central rock quadrant cut removed'],'p2Issues':[{'id':'willow-repair-boundaries','detail':'Narrow straight material/leaf-color steps remain near expanded patch bottom y1616 and right x2978; geometry generally retained.','nativeEditAttempts':2,'status':'deferred_unpassed'},{'id':'rightmost-foliage-repair-boundaries','detail':'Original y1024 clipped band improved; narrow local border color variation remains around x3775,y914..1152.','nativeEditAttempts':2,'status':'deferred_unpassed'},{'id':'rock-repair-boundaries','detail':'Central L-shaped cut removed; texture/lighting step remains around x2445 and y2849; weak bottom step y4034.','nativeEditAttempts':2,'status':'deferred_unpassed'}],'p3Notes':['Small hand-painted grain differences around otherwise continuous roof.'],'selectionReason':'Best reviewed complete candidate after two native repair rounds. Enlarged integer source crops reduce new rectangular cutoffs. Residual boundary defects remain explicitly unpassed.','nativeCoreCount':16,'nativeRepairCount':8,'actualModel':None,'actualQuality':None,'route':'builtin','sharedWorldEdges':'pending; north/west/east/south adjoining tiles unfinished'}
dest=Q/'internal-review-v6.json';assert not dest.exists();dest.write_text(json.dumps(review,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
p=read(T/'tile-progress.json');p.update({'status':review['status'],'candidate':str(f),'candidateSha256':sha(f),'fullInternalReview':str(dest),'internalPassed4kCount':0,'formalAcceptedCount':0,'pendingRepairs':[i['id'] for i in review['p2Issues']],'nextPatch':None,'nextRootTile':'r01_c14','inflightGeneration':None,'updatedAt':datetime.now(timezone.utc).isoformat()});(T/'tile-progress.json').write_text(json.dumps(p,indent=2)+'\n')
print(json.dumps({'candidate':str(f),'sha256':sha(f),'status':review['status'],'internalPassed4kCount':0,'pendingIssues':len(review['p2Issues'])}))

